// Content loader: NEBULA content (../content) as Starlight's `docs` collection.
//
// Content is read in place and never edited. Mappings:
// - `type: slides` pages show their study view (generated by
//   tools/build_study.py next to the source); the page keeps the source's
//   id, so /modules/<m>/slides and "Edit this page" point at the deck source
// - `type: exercise` bodies are wrapped in a Starlight aside
// - module index pages get a table of the module's pages in `order`
// - NEBULA root-absolute links (/main/x, /modules/m/p) point at this site;
//   links to modules that are not in it go to the current NEBULA site
// Every page's frontmatter is validated by the collection schema
// (content.config.ts); module index pages additionally by moduleSchema.

import { readFileSync } from 'node:fs';
import { join, relative } from 'node:path';
import { pathToFileURL } from 'node:url';
import type { Loader } from 'astro/loaders';
import { z } from 'astro/zod';
import { loadSource, splitFrontmatter } from './nebula.mjs';

interface SourceOptions {
	/** Content repo checkout, absolute path */
	root: string;
	/** URL prefix for "Edit this page", e.g. https://github.com/o/r/edit/main/content/ */
	editBase?: string;
}

interface Options {
	sources: SourceOptions[];
	/** Site base path, e.g. /NEBULA_2.0/starlight */
	base: string;
	/** Extra Markdown pages of this project: id -> absolute file path */
	extraPages?: Record<string, string>;
}

export const moduleSchema = z.object({
	title: z.string(),
	category: z.string(),
	order: z.number(),
	abstract: z.string(),
	thumbnail: z.string(),
	visibility: z.enum(['visible', 'hidden']),
});

const SITE_LINK = /(\]\(|href=")(\/(?:main|modules)(?:\/[^)"#?\s]*)?)(#[^)"\s]*)?/g;
const STUDY_HEADING = /<h([1-6]) id="([^"]+)"/g;
const ANCHOR_LINK = /(<a class="sl-anchor-link" href="#)([^"]+)"/g;

export function nebulaLoader(opts: Options): Loader {
	return {
		name: 'nebula-loader',
		async load(ctx) {
			ctx.store.clear();
			const base = opts.base.replace(/\/$/, '');

			for (const src of opts.sources) {
				const source = loadSource(src.root);
				const ids = new Set<string>([
					...source.main.map((p) => p.id),
					...source.modules.flatMap((m) => [m.index.id, ...m.pages.map((p) => p.id)]),
				]);
				const rewrite = (body: string) =>
					body.replace(SITE_LINK, (all, pre, path, frag = '') => {
						const id = path.replace(/^\/|\/$/g, '');
						if (ids.has(id)) return `${pre}${base}/${id}.html${frag}`;
						if (id.startsWith('modules/')) return `${pre}${source.upstreamSite}${path}${frag}`;
						ctx.logger.warn(`unresolved site link ${path}`);
						return all;
					});

				const add = async (page: any, body: string, extra: Record<string, unknown> = {}) => {
					const meta = page.meta;
					const type = meta.type as string | undefined;
					const data = {
						...meta,
						...extra,
						editUrl: src.editBase
							? src.editBase + relative(src.root, page.file).split('\\').join('/')
							: false,
					};
					const filePath = relative(process.cwd(), page.file);
					const parsed = await ctx.parseData({ id: page.id, data, filePath });
					const rendered = await ctx.renderMarkdown(rewrite(body), {
						fileURL: pathToFileURL(page.file),
					});
					if (type === 'slides') {
						// Heading ids would duplicate the slide ids on the study
						// <section>s ("About copyright" -> #about-copyright).
						rendered.html = rendered.html
							.replace(STUDY_HEADING, '<h$1 id="$2--h"')
							.replace(ANCHOR_LINK, '$1$2--h"');
						for (const h of rendered.metadata?.headings ?? []) h.slug += '--h';
					}
					ctx.store.set({
						id: page.id,
						data: parsed,
						body,
						rendered,
						filePath,
						// Markdown images (![](media/x.png)) are resolved and optimised
						// by Astro only when listed here, as the glob loader does.
						assetImports: rendered.metadata?.imagePaths,
						digest: ctx.generateDigest(body + JSON.stringify(data)),
					});
				};

				for (const page of source.main) await add(page, page.body);

				for (const mod of source.modules) {
					const check = moduleSchema.safeParse(mod.meta);
					if (!check.success) {
						throw new Error(
							`${relative(process.cwd(), mod.index.file)}: invalid module frontmatter\n` +
								z.prettifyError(check.error),
						);
					}
					const rows = mod.pages.map(
						(p: any) => `| [${p.meta.title}](${base}/${p.id}.html) | ${p.meta.type ?? ''} |`,
					);
					const table = `\n\n| Page | Type |\n|---|---|\n${rows.join('\n')}\n`;
					// Starlight shows `description` only in metadata; the abstract
					// opens the module page as in NEBULA.
					await add(mod.index, `${mod.meta.abstract}\n\n${mod.index.body}${table}`, {
						module: mod.slug,
						description: mod.meta.abstract,
					});

					for (const page of mod.pages) {
						let body = page.body;
						if (page.meta.type === 'slides') {
							const study = page.file.replace(/\.md$/, '.study.md');
							body = splitFrontmatter(readFileSync(study, 'utf8'))[1];
						} else if (page.meta.type === 'exercise') {
							body = `:::tip[Exercise]\n${body.trim()}\n:::\n`;
						}
						await add(page, body, { module: mod.slug });
					}
				}
			}

			for (const [id, file] of Object.entries(opts.extraPages ?? {})) {
				const [meta, body] = splitFrontmatter(readFileSync(file, 'utf8'));
				await add_extra(ctx, id, file, meta, body);
			}
		},
	};
}

async function add_extra(ctx: any, id: string, file: string, meta: any, body: string) {
	const filePath = relative(process.cwd(), file);
	const data = await ctx.parseData({ id, data: { ...meta, editUrl: false }, filePath });
	const rendered = await ctx.renderMarkdown(body, { fileURL: pathToFileURL(file) });
	ctx.store.set({ id, data, body, rendered, filePath, digest: ctx.generateDigest(body) });
}
